SET NAMES utf8mb4;

UPDATE products SET blurb = 'The CabKing 8 Inch Grinder Polisher is an eight-station cabbing machine driven by a 3/4 hp, 1800 rpm direct-drive motor.

Six wheel positions and two end stations give you room to run coarse-to-fine stages side by side, with a shut-off valve above each wheel so water goes only where you are working. A clean-water system keeps grit from one stage from contaminating the next, and a built-in lamp lights the work area. It ships with metal- and resin-bond diamond wheels from 80 to 3000 grit, a 360 grit flat lap, a canvas polishing pad, diamond paste, a separate submersible pump, splash hoods, pans, hand rests, goggles and an apron. Footprint is about 40 in wide by 13 in deep and it weighs roughly 75 lb. The motor and parts carry a one-year manufacturer\'s warranty (wheels excluded).', features = '["Direct drive motor, 110/115V, 3/4 hp, 1800 rpm", "Separate water shut-off valve above each wheel and grinding/polishing pad", "8 work stations: 6 wheels plus 2 end stations", "Clean water system keeps work stations free of contamination", "6W, 12V lamp", "Manufacturer\'s 1 Year warranty on the motor and parts (wheels not covered)", "Free shipping"]', included = '["Two metal bonded diamond wheels, 8\\" x 1-1/2\\" (80 and 220 grit)", "Four 8\\" x 2\\" resin bonded diamond wheels, 1 of each grit (280, 600, 1200, and 3000 grit)", "One 8\\" 1/2\\" diamond flat lap, 360 grit", "One canvas polishing pad, 5-1/2\\", no hole", "One 2-gram syringe of diamond paste compound, 14,000 grit", "Goggles", "Apron", "605 GPH, 30W submersible pump, supplied separately", "Splash hoods made of stainless steel", "Clear splash shields, adjustable", "Plastic pans that have drain holes", "Splash guards for the sides", "Hand rests made of metal"]', specs = '{"Weight": "75.00 lb", "Width": "40 inches", "Height": "14 inches", "Depth": "13 inches"}', warranty = 'Manufacturer\'s 1 Year warranty covers the motor and parts, but not the wheels' WHERE id = 'cabking-8-inch-grinder-polisher';
UPDATE products SET blurb = 'The Gemini Revolution XT Ring Saw slices tile and stone up to 6 cm thick with a 10 inch sintered diamond blade.

Because the blade is a ring rather than a disc, the length and width of the piece you can pass through it are effectively unlimited, and the saw cuts in both directions, which makes inside and outside curves easy to follow. It is fully self-contained and needs no water pump. The kit includes the saw, a slide tray, the stand assembly and your choice of single- or double-sided blade. The footprint is roughly 31 x 20 x 13 in.', features = '["Cuts in both forward and reverse, which makes curves simple", "Takes a 10 inch Sintered Diamond Blade (Single-sided and Double-sided blades offered)", "Handles inside and outside radius curves", "No limit on cut length or width", "Cuts tile and stone up to 6 cm thick", "Self-contained, with no water pump", "Heavy duty but portable", "Size is 31\\" x 20\\" x 13\\"", "Free shipping"]', included = '["XT Revolution Ring Saw", "Slide Tray Kit", "Stand Assembly", "Blade of your choice"]', specs = '{"Dimensions": "31\\" x 20\\" x 13\\"", "Max material thickness": "6 cm", "Blade size": "10\\" Sintered Diamond Blade"}', warranty = NULL WHERE id = 'gemini-revolution-xt-ring-saw';
UPDATE products SET blurb = 'The Covington 40 Pound Production Rock Tumbler is built for shops that polish stone in volume rather than by the handful.

A 1/3 hp motor turns a powder-coated hexagonal barrel with a rubber liner, about 9 in across and 11 in deep inside, on dual rubber-covered 5/8 in steel shafts. The chassis is powder-coated steel with heavy-duty sealed ball bearings. It comes with instructions, the manufacturer\'s warranty and a sample of Old Miser.', features = '["1/3 hp motor", "Steel chassis with powder coat finish", "Sealed ball bearings, heavy duty", "Hexagonal barrel with powder coat finish and rubber liner", "Barrel interior measures about 9\\" across and 11\\" deep", "5/8\\" steel support shafts, rubber covered and dual driven"]', included = '["Old Miser sample", "Instruction sheet", "Manufacturer\'s warranty"]', specs = '{"Barrel (inner)": "~9\\" across x 11\\" deep", "Motor": "1/3 hp"}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-40-pound-production-rock-tumbler';
UPDATE products SET blurb = 'The Covington Bead Mill grinds round beads from 5/16 in to 3/4 in in diameter, up to 20 half-inch beads in one load.

It runs on a 1/3 hp, 110V motor in a dual-speed configuration, 380 rpm and 250 rpm, inside a powder-coated heavy-gauge steel housing. The chamber head lifts off quickly for cleaning. It measures about 24 in wide, 16 in tall and 12 in deep and weighs 75 lb. Instructions and the manufacturer\'s warranty are included.', features = '["Produces beads from 5/16\\" to 3/4\\" in diameter", "1/3 hp, 110V, 60 Hz motor", "Small, portable size", "Housed in heavy gauge powder-coated steel", "Chamber head comes off quickly for easy cleaning", "Grinds as many as 20 half inch beads per run", "Dual speed model runs at 380 rpm and 250 rpm", "Comes with instructions", "Manufacturer\'s warranty", "Free shipping"]', included = '["Instructions"]', specs = '{"Weight": "75 lb", "Width": "24 inches", "Height": "16 inches", "Depth": "12 inches"}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-bead-mill';
UPDATE products SET blurb = 'The Covington Large Sphere Machine turns rough stone into spheres from 1-1/4 in up to 9 in across.

Two 1/3 hp motors drive spring-loaded cutting heads with an adjustable cutting angle. Grit is applied automatically from a slurry bowl, and shielded arbor shafts and bearings keep abrasive out of the works. It sits in a large metal cabinet with a shelf, weighs about 250 lb, and comes with two 8 in spiral polishing buffs, two grit pans, the slurry bowl and one pair of cutter cups in the size you choose.', features = '["Makes spheres from 1-1/4\\" to 9\\" in diameter", "Two 1/3 hp motors", "Two 8\\" x 1/4\\" x 1\\" spiral polishing buffs", "Two grit pans", "Slurry bowl applies grit automatically", "Cutting heads are spring loaded", "Adjustable cutting angle", "Arbor shafts and bearings are shielded", "Large metal cabinet that has a shelf", "Powder coat for durability and rust resistance", "Made in USA", "Free shipping"]', included = '["Two spiral polishing buffs, 8\\" x 1/4\\" x 1\\"", "Two grit pans", "Slurry bowl", "One pair of cutter cups (choose from 1\\", 1-3/8\\", 2-3/8\\", 3-3/8\\" or 4-3/8\\")", "Large metal cabinet with a shelf", "Instructions"]', specs = '{"Weight": "250 lb"}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-large-sphere-machine';
UPDATE products SET blurb = 'The Covington Professional Glass Lathe is a variable-speed lathe for glass work, with 12 in of reach and a 1 hp DC motor that runs from 0 to 1850 rpm.

The frame is solid billet aluminum, and the shaft is turned, ground and polished stainless steel to keep vibration down. The spindle is 1 in with a Morse 3 taper, a drift key is supplied, and the water-resistant motor is controlled from a NEMA 4X box with a 5 ft power cord. It is a quiet machine for its class.', features = '["12\\" reach", "Shaft is turned, ground and polished to limit vibration", "Morse 3 taper", "1\\" spindle with drift key", "1 hp DC water resistant motor with variable speed", "0 to 1850 rpm range", "Quiet running", "Shaft made of stainless steel", "NEMA 4X control box", "5 foot power cord", "Built from solid billet aluminum of aircraft quality", "Base has 4 mounting holes", "Free shipping"]', included = '["1\\" spindle with drift key"]', specs = '{"Motor": "1 hp DC variable speed", "Speed range": "0-1850 rpm", "Reach": "12\\""}', warranty = NULL WHERE id = 'covington-professional-glass-lathe';
UPDATE products SET blurb = 'The Covington 30 Inch Slab Saw is a heavy welded-steel slab saw with a six-speed power feed and an automatic shut-off at the end of the cut.

The frame is welded separately from the chassis so it will not warp, a quick-return system lets you move the carriage by hand to any position, and an over-running clutch adjusts the feed from soft to hard rock on its own. The tank holds 22 gallons of coolant, the saw runs on 220V/60Hz and weighs 675 lb. A vise, motor and Covington\'s best diamond blade are included.', features = '["Heavy welded steel chassis with powder coat", "Frame is welded separately so it does not warp", "Six-speed power feed that shuts off automatically", "Quick return system lets the carriage be moved by hand to any position", "Over-running clutch adjusts on its own from soft to hard rock", "Cross feed allows 8\\" of material to be slabbed", "Arbor and flange are one piece, mounted in the housing", "Heavy-duty ball bearings, neoprene sealed and greased for life", "One-piece vise carriage on solid key stock with a channel guide", "Holds 22 gallons of coolant", "220V, 60Hz", "Made in USA", "Free shipping"]', included = '["Vise", "Motor", "Covington\'s Best Diamond Blade"]', specs = '{"Weight": "675 lb", "Power": "220V, 60Hz", "Coolant capacity": "22 gallons"}', warranty = NULL WHERE id = 'covington-30-inch-slab-saw';
UPDATE products SET blurb = 'Covington Platinum 301 Diamond Saw Blades are sintered blades made for hard material such as agate, petrified wood and jade.

Compared with standard blades they carry a higher diamond concentration and a higher-carbon steel core that holds tension better. The sintered diamond kerf is solid, which helps both cutting speed and coolant flow. Shipping is free within the lower 48 states.', features = '["More diamond concentration", "Steel core with more carbon for better tension memory", "Solid diamond sintered kerf gives better cutting and coolant flow", "Well suited to hard materials such as agate, petrified wood and jade", "Free shipping (lower 48 states)"]', included = '[]', specs = '{}', warranty = NULL WHERE id = 'covington-platinum-301-diamond-saw-blades';
